package dev.celerbi.easyfarmersdelightcompat.compat.jade;
import dev.celerbi.easyfarmersdelightcompat.EasyFarmersDelightCompat;import dev.celerbi.easyfarmersdelightcompat.blockentity.CompatFarmerBlockEntity;import net.minecraft.nbt.CompoundTag;import net.minecraft.nbt.Tag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;import snownee.jade.api.BlockAccessor;import snownee.jade.api.IBlockComponentProvider;import snownee.jade.api.IServerDataProvider;import snownee.jade.api.ITooltip;import snownee.jade.api.config.IPluginConfig;
public enum FarmerKnifeJadeProvider implements IBlockComponentProvider,IServerDataProvider<BlockAccessor>{INSTANCE;private static final ResourceLocation UID=ResourceLocation.fromNamespaceAndPath(EasyFarmersDelightCompat.MOD_ID,"farmer_knife");private static final String KEY="EfdcFarmerKnife";public void appendServerData(CompoundTag data,BlockAccessor a){data.remove(KEY);if(a.getBlockEntity() instanceof CompatFarmerBlockEntity f&&f.variant().isRich()){ItemStack k=f.getKnife();if(!k.isEmpty())data.put(KEY,k.save(a.getLevel().registryAccess()));}}public void appendTooltip(ITooltip t,BlockAccessor a,IPluginConfig c){CompoundTag d=a.getServerData();if(!d.contains(KEY,Tag.TAG_COMPOUND))return;ItemStack k=ItemStack.parseOptional(a.getLevel().registryAccess(),d.getCompound(KEY));if(!k.isEmpty())t.add(Component.translatable("jade.easyfarmersdelightcompat.farmer.knife",k.getHoverName()));}public ResourceLocation getUid(){return UID;}}
